//! The Reference page's view of a kind's JSON schema (design §12): one row
//! per field with its type, whether it is required, its default and whether
//! it may carry a secret, read from what `GET /catalog` serves. The schemas
//! are generated by schemars from the task specs, so the reference cannot
//! drift from the binary.

use serde_json::Value;

/// How deep nested objects are expanded before a field is shown as `object`.
pub const MAX_DEPTH: usize = 3;

/// The extension keyword `SecretField` puts in its schema.
pub const SECRET_KEYWORD: &str = "x-buckle-secret";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Field {
    /// Dotted for nested fields: `expect.status`; `[]` for array items.
    pub path: String,
    pub depth: usize,
    pub ty: String,
    pub required: bool,
    pub default: Option<String>,
    pub description: Option<String>,
    pub secret: bool,
    /// Allowed values, for an enumeration.
    pub options: Vec<String>,
}

/// The fields a schema describes, siblings ordered required first and then
/// by name, each followed by its own nested fields.
pub fn fields(schema: &Value) -> Vec<Field> {
    let mut out = Vec::new();
    let root = Resolver { root: schema };
    root.object(schema, "", 0, &mut out);
    out
}

/// A one-line description of a schema with no properties of its own.
pub fn describe(schema: &Value) -> String {
    Resolver { root: schema }.ty(schema)
}

struct Resolver<'a> {
    root: &'a Value,
}

impl<'a> Resolver<'a> {
    /// Follows a `$ref` into `$defs`/`definitions`.
    fn resolve(&self, schema: &'a Value) -> &'a Value {
        let mut current = schema;
        for _ in 0..8 {
            let Some(reference) = current.get("$ref").and_then(Value::as_str) else {
                break;
            };
            let Some(path) = reference.strip_prefix("#/") else {
                break;
            };
            let mut target = self.root;
            for part in path.split('/') {
                match target.get(part) {
                    Some(t) => target = t,
                    None => return current,
                }
            }
            current = target;
        }
        current
    }

    /// The properties and required list of an object schema, merging `allOf`
    /// (how schemars writes `#[serde(flatten)]`).
    fn properties(&self, schema: &'a Value) -> (Vec<(&'a str, &'a Value)>, Vec<&'a str>) {
        let schema = self.resolve(schema);
        let mut props: Vec<(&str, &Value)> = Vec::new();
        let mut required: Vec<&str> = Vec::new();
        if let Some(map) = schema.get("properties").and_then(Value::as_object) {
            props.extend(map.iter().map(|(k, v)| (k.as_str(), v)));
        }
        if let Some(list) = schema.get("required").and_then(Value::as_array) {
            required.extend(list.iter().filter_map(Value::as_str));
        }
        for part in schema
            .get("allOf")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
        {
            let (p, r) = self.properties(part);
            for (k, v) in p {
                if !props.iter().any(|(existing, _)| *existing == k) {
                    props.push((k, v));
                }
            }
            required.extend(r);
        }
        (props, required)
    }

    fn object(&self, schema: &'a Value, prefix: &str, depth: usize, out: &mut Vec<Field>) {
        let (mut props, required) = self.properties(schema);
        props.sort_by(|a, b| {
            let ra = required.contains(&a.0);
            let rb = required.contains(&b.0);
            rb.cmp(&ra).then(a.0.cmp(b.0))
        });
        for (name, prop) in props {
            let path = if prefix.is_empty() {
                name.to_string()
            } else {
                format!("{prefix}.{name}")
            };
            let resolved = self.resolve(prop);
            out.push(Field {
                path: path.clone(),
                depth,
                ty: self.ty(prop),
                required: required.contains(&name),
                default: prop
                    .get("default")
                    .or_else(|| resolved.get("default"))
                    .map(compact),
                description: text(prop, "description").or_else(|| text(resolved, "description")),
                secret: self.secret(prop),
                options: self.options(prop),
            });
            if depth + 1 < MAX_DEPTH {
                let nested = self.nested_object(prop);
                if let Some((nested, suffix)) = nested {
                    self.object(nested, &format!("{path}{suffix}"), depth + 1, out);
                }
            }
        }
    }

    /// The object schema a field's nested fields come from: the field itself,
    /// its non-null `anyOf` variant (an `Option<Struct>`), or its array items.
    fn nested_object(&self, schema: &'a Value) -> Option<(&'a Value, &'static str)> {
        let schema = self.non_null(self.resolve(schema));
        if !self.properties(schema).0.is_empty() {
            return Some((schema, ""));
        }
        if let Some(items) = schema.get("items") {
            let items = self.non_null(self.resolve(items));
            if !self.properties(items).0.is_empty() {
                return Some((items, "[]"));
            }
        }
        None
    }

    /// For `anyOf: [X, {type: null}]`, the X.
    fn non_null(&self, schema: &'a Value) -> &'a Value {
        for key in ["anyOf", "oneOf"] {
            if let Some(variants) = schema.get(key).and_then(Value::as_array) {
                let real: Vec<&Value> = variants.iter().filter(|v| !is_null(v)).collect();
                if real.len() == 1 {
                    return self.resolve(real[0]);
                }
            }
        }
        schema
    }

    fn secret(&self, schema: &'a Value) -> bool {
        let resolved = self.resolve(schema);
        if [schema, resolved]
            .iter()
            .any(|s| s.get(SECRET_KEYWORD).and_then(Value::as_bool) == Some(true))
        {
            return true;
        }
        ["anyOf", "oneOf", "allOf"].iter().any(|key| {
            resolved
                .get(*key)
                .and_then(Value::as_array)
                .is_some_and(|vs| vs.iter().any(|v| self.secret(v)))
        }) || ["items", "additionalProperties"].iter().any(|key| {
            resolved
                .get(*key)
                .is_some_and(|v| v.is_object() && self.secret(v))
        })
    }

    fn options(&self, schema: &'a Value) -> Vec<String> {
        let schema = self.non_null(self.resolve(schema));
        if let Some(values) = schema.get("enum").and_then(Value::as_array) {
            return values.iter().map(compact).collect();
        }
        for key in ["oneOf", "anyOf"] {
            if let Some(variants) = schema.get(key).and_then(Value::as_array) {
                let consts: Vec<String> = variants
                    .iter()
                    .filter(|v| !is_null(v))
                    .filter_map(|v| {
                        let v = self.resolve(v);
                        v.get("const").map(compact).or_else(|| {
                            match v.get("enum").and_then(Value::as_array) {
                                Some(e) if e.len() == 1 => Some(compact(&e[0])),
                                _ => None,
                            }
                        })
                    })
                    .collect();
                if !consts.is_empty() {
                    return consts;
                }
            }
        }
        Vec::new()
    }

    /// A short type name: `string`, `integer?`, `array of string`,
    /// `map of string`, `string | array of string`.
    fn ty(&self, schema: &'a Value) -> String {
        let schema = self.resolve(schema);
        if schema.get(SECRET_KEYWORD).and_then(Value::as_bool) == Some(true) {
            return "secret string".into();
        }
        if schema.get("const").is_some() {
            return "constant".into();
        }
        if schema.get("enum").is_some() {
            return "enum".into();
        }
        for key in ["anyOf", "oneOf"] {
            if let Some(variants) = schema.get(key).and_then(Value::as_array) {
                let nullable = variants.iter().any(is_null);
                let real: Vec<&Value> = variants.iter().filter(|v| !is_null(v)).collect();
                if !self.options(schema).is_empty() {
                    return if nullable {
                        "enum?".into()
                    } else {
                        "enum".into()
                    };
                }
                let mut names: Vec<String> = real.iter().map(|v| self.ty(v)).collect();
                names.dedup();
                let joined = names.join(" | ");
                return if nullable && real.len() == 1 {
                    format!("{joined}?")
                } else if nullable {
                    format!("{joined} | null")
                } else {
                    joined
                };
            }
        }
        let types: Vec<&str> = match schema.get("type") {
            Some(Value::String(t)) => vec![t.as_str()],
            Some(Value::Array(ts)) => ts.iter().filter_map(Value::as_str).collect(),
            _ => Vec::new(),
        };
        let nullable = types.contains(&"null");
        let mut names: Vec<String> = types
            .iter()
            .filter(|t| **t != "null")
            .map(|t| match *t {
                "array" => match schema.get("items") {
                    Some(items) => format!("array of {}", self.ty(items)),
                    None => "array".into(),
                },
                "object" => match schema.get("additionalProperties") {
                    Some(v) if v.is_object() && self.properties(schema).0.is_empty() => {
                        format!("map of {}", self.ty(v))
                    }
                    _ => "object".into(),
                },
                other => match schema.get("format").and_then(Value::as_str) {
                    Some(f) if other == "string" => format!("string ({f})"),
                    _ => other.to_string(),
                },
            })
            .collect();
        if names.is_empty() {
            names.push(if self.properties(schema).0.is_empty() {
                "any".into()
            } else {
                "object".into()
            });
        }
        let joined = names.join(" | ");
        if nullable {
            format!("{joined}?")
        } else {
            joined
        }
    }
}

fn is_null(v: &Value) -> bool {
    v.get("type").and_then(Value::as_str) == Some("null") || v.get("const") == Some(&Value::Null)
}

fn text(v: &Value, key: &str) -> Option<String> {
    v.get(key)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
}

/// A value as a reader would write it in `module.yaml`.
fn compact(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        other => other.to_string(),
    }
}

/// The schema's own description, if it has one.
pub fn description(schema: &Value) -> Option<String> {
    text(schema, "description")
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn template_schema() -> Value {
        json!({
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "Spec",
            "type": "object",
            "properties": {
                "src": {"type": "string", "description": "Template path."},
                "dest": {"type": "string", "description": "Destination."},
                "backup": {"type": "boolean", "default": false},
                "validate": {"type": ["array", "null"], "items": {"type": "string"}, "default": null},
                "password": {"type": "string", "x-buckle-secret": true, "description": "May reference secrets."},
                "env": {"type": "object", "additionalProperties": {"$ref": "#/$defs/SecretField"}},
                "state": {"$ref": "#/$defs/State", "default": "present"},
                "expect": {"anyOf": [{"$ref": "#/$defs/Expect"}, {"type": "null"}]}
            },
            "allOf": [{"$ref": "#/$defs/FilePerms"}],
            "required": ["src", "dest"],
            "$defs": {
                "SecretField": {"type": "string", "x-buckle-secret": true},
                "State": {"oneOf": [
                    {"const": "present", "description": "exists"},
                    {"const": "absent", "description": "removed"}
                ]},
                "Expect": {"type": "object", "properties": {
                    "status": {"type": "integer", "format": "uint16", "default": 200},
                    "body_contains": {"type": ["string", "null"]}
                }, "required": ["status"]},
                "FilePerms": {"type": "object", "properties": {
                    "mode": {"type": ["string", "null"], "description": "Octal mode."},
                    "owner": {"type": ["string", "null"]}
                }}
            }
        })
    }

    #[test]
    fn fields_come_out_required_first_with_types_defaults_and_secrets() {
        let f = fields(&template_schema());
        let paths: Vec<&str> = f.iter().map(|x| x.path.as_str()).collect();
        assert_eq!(
            paths,
            vec![
                "dest",
                "src",
                "backup",
                "env",
                "expect",
                "expect.status",
                "expect.body_contains",
                "mode",
                "owner",
                "password",
                "state",
                "validate"
            ]
        );
        let get = |p: &str| f.iter().find(|x| x.path == p).unwrap();
        assert!(get("src").required && !get("backup").required);
        assert_eq!(get("src").description.as_deref(), Some("Template path."));
        assert_eq!(get("backup").default.as_deref(), Some("false"));
        assert_eq!(get("validate").ty, "array of string?");
        assert_eq!(get("env").ty, "map of secret string");
        assert!(get("env").secret, "a map of secrets carries secrets");
        assert!(get("password").secret);
        assert!(!get("src").secret);
        assert_eq!(get("state").options, vec!["present", "absent"]);
        assert_eq!(get("state").default.as_deref(), Some("present"));
        assert_eq!(get("expect").ty, "object?");
        assert_eq!(get("expect.status").depth, 1);
        assert!(get("expect.status").required);
        assert_eq!(get("expect.status").ty, "integer");
        assert_eq!(get("mode").description.as_deref(), Some("Octal mode."));
    }

    #[test]
    fn schemas_without_properties_are_described_not_tabulated() {
        assert!(fields(&Value::Null).is_empty());
        assert!(fields(&json!({"type": "object", "additionalProperties": true})).is_empty());
        assert_eq!(
            describe(&json!({"type": "string", "format": "uri"})),
            "string (uri)"
        );
        assert_eq!(
            describe(
                &json!({"anyOf": [{"type": "string"}, {"type": "array", "items": {"type": "string"}}]})
            ),
            "string | array of string"
        );
    }

    #[test]
    fn array_items_with_properties_are_expanded() {
        let schema = json!({
            "type": "object",
            "properties": {"rules": {"type": "array", "items": {"type": "object",
                "properties": {"port": {"type": "integer"}}, "required": ["port"]}}}
        });
        let f = fields(&schema);
        assert_eq!(f[1].path, "rules[].port");
        assert!(f[1].required);
    }
}
